update hygieia.skincare_tips set
  body_el = 'Το πρόβλημα με το ημιμόνιμο δεν είναι το προϊόν αλλά η αφαίρεση: το λιμάρισμα και το ξύσιμο λεπταίνουν την πλάκα κάθε φορά. Μετά από δύο-τρεις εφαρμογές άφησε τα νύχια γυμνά για δύο εβδομάδες με λάδι επωνυχίων κάθε βράδυ. Στο σαλόνι ζήτα αφαίρεση με μούλιασμα, όχι ξύσιμο.',
  body_en = 'The problem with semi-permanent polish is not the product but the removal: filing and scraping thin the plate every time. After two or three applications leave the nails bare for two weeks with cuticle oil every night. At the salon ask for soak-off removal, not scraping.'
where slug = 'nails-gel-and-acrylic-take-breaks';

